window.PROBABILITY_BOOK_DATA = {"chapter":6,"title":"Normal & exponential distributions","total":78,"range":[430,507],"questions":[{"id":430,"question":"A mobile conversation lasts X minutes, with density f(x) = (1/3)e^(−x/3) for x ≥ 0. Find P(X > 5).","page":37,"marks":1,"answer":"More than five minutes: 0.1888756","steps":[{"title":"Use the exponential survival function","formula":"λ = 0.33333333. For t ≥ 0, P(X > t) = e^(−λt)."},{"title":"More than five minutes","formula":"e^(−1.6666667) ≈ 0.1888756."}],"shareImage":"share/q430.jpg","shareImageSize":[1358,266]},{"id":431,"question":"A random variable 𝑋 has an exponential\ndistribution with probability distribution function is\ngiven by\n𝑓(𝑥) = 3𝑒−3𝑥 for 𝑥 > 0\n= 0 otherwise\nFind probability that 𝑋 is not less than 2.","page":37,"marks":1,"answer":"P(X ≥ 2): 0.0024787522","steps":[{"title":"Use the exponential survival function","formula":"λ = 3. For t ≥ 0, P(X > t) = e^(−λt)."},{"title":"P(X ≥ 2)","formula":"e^(−6) ≈ 0.0024787522."}],"shareImage":"share/q431.jpg","shareImageSize":[1358,331]},{"id":432,"question":"The mean and variance of the density function\nf (x) = 2e−2x are","page":37,"marks":1,"answer":"Mean = 1/2. Variance = 1/4.","steps":[{"title":"Set up the calculation","formula":"The density 2e^(−2x) has rate λ = 2."},{"title":"Calculate","formula":"Use E[X] = 1/λ and Var(X) = 1/λ²."}],"shareImage":"share/q432.jpg","shareImageSize":[1358,203]},{"id":433,"question":"If 𝑋 is random variable which follows an\nexponential distribution with parameter 𝜆 with\n𝑃(𝑋 ≤ 1) = 𝑃(𝑋 > 1) , what is 𝑉𝑎𝑟(𝑥)?","page":37,"marks":1,"answer":"1/(ln 2)²","steps":[{"title":"Set up the calculation","formula":"P(X ≤ 1) = P(X > 1), so each probability equals 1/2."},{"title":"Calculate","formula":"e^(−λ) = 1/2 gives λ = ln 2. Therefore Var(X) = 1/(ln 2)²."}],"shareImage":"share/q433.jpg","shareImageSize":[1358,235]},{"id":434,"question":"The annual precipitation data of a city is normally\ndistributed with mean and standard deviation as\n1000 mm and 200 mm, respectively. The\nprobability that the annual precipitation will be\nmore than 1200 mm is,","page":37,"marks":1,"answer":"More than 1200 mm: 0.15865525","steps":[{"title":"Standardize X","formula":"Use Z = (X − 1000)/200, with Φ(z) = P(Z ≤ z)."},{"title":"More than 1200 mm","formula":"1 − Φ(1) ≈ 0.15865525."}],"note":"The practice book option is “less than 50%”. The calculated chance is about 15.87%.","shareImage":"share/q434.jpg","shareImageSize":[1358,297]},{"id":435,"question":"The normal probability density function curve is\nsymmetrical about the mean, µ, i.e., the area to the\nright ofthe mean is the same as the area to the left\nof the mean. This means that\n𝑃(𝑋 < µ) = 𝑃(𝑋 > µ) is equal to:","page":37,"marks":1,"answer":"0.5","steps":[{"title":"Set up the calculation","formula":"The two sides of a normal curve about μ have equal area."},{"title":"Calculate","formula":"The total area is 1 and the point X = μ has probability zero, so each side has area 0.5."}],"shareImage":"share/q435.jpg","shareImageSize":[1358,304]},{"id":436,"question":"The range of normal distribution is:","page":37,"marks":1,"answer":"(−∞, ∞)","steps":[{"title":"Set up the calculation","formula":"A normal density is positive at every real x."},{"title":"Calculate","formula":"Its support extends over all real numbers."}],"shareImage":"share/q436.jpg","shareImageSize":[1358,201]},{"id":437,"question":"If 𝑋~𝑁(100,64), then standard deviation 𝜎 is\n_____.","page":37,"marks":1,"answer":"8","steps":[{"title":"Set up the calculation","formula":"In N(100,64), the second parameter is σ²."},{"title":"Calculate","formula":"σ = √64 = 8."}],"shareImage":"share/q437.jpg","shareImageSize":[1358,202]},{"id":438,"question":"If 𝑋~𝑁 (200,49), then standard deviation 𝜎 is\n_____.","page":37,"marks":1,"answer":"7","steps":[{"title":"Set up the calculation","formula":"In N(200,49), the second parameter is σ²."},{"title":"Calculate","formula":"σ = √49 = 7."}],"shareImage":"share/q438.jpg","shareImageSize":[1358,209]},{"id":439,"question":"In a standard normal distribution, the area to the left\nof Z = 1 is:","page":37,"marks":1,"answer":"Left of Z = 1: 0.84134475","steps":[{"title":"Standardize X","formula":"Use Z = (X − 0)/1, with Φ(z) = P(Z ≤ z)."},{"title":"Left of Z = 1","formula":"Φ(1) ≈ 0.84134475."}],"shareImage":"share/q439.jpg","shareImageSize":[1358,201]},{"id":440,"question":"If 𝑍 is a standard normal variate, then 𝑃(−2.33 ≤\n𝑍 ≤ 2.33) is equal to _____.","page":37,"marks":1,"answer":"Central area: 0.98019385","steps":[{"title":"Standardize X","formula":"Use Z = (X − 0)/1, with Φ(z) = P(Z ≤ z)."},{"title":"Central area","formula":"Φ(2.33) − Φ(-2.33) ≈ 0.98019385."}],"shareImage":"share/q440.jpg","shareImageSize":[1358,203]},{"id":441,"question":"If 𝑍 is a standard normal variate, then 𝑃(−1.65 ≤\n𝑍 ≤ 1.65) is equal to _____.","page":37,"marks":1,"answer":"Central area: 0.90105706","steps":[{"title":"Standardize X","formula":"Use Z = (X − 0)/1, with Φ(z) = P(Z ≤ z)."},{"title":"Central area","formula":"Φ(1.65) − Φ(-1.65) ≈ 0.90105706."}],"shareImage":"share/q441.jpg","shareImageSize":[1358,204]},{"id":442,"question":"If 𝑍 is a standard normal variate, then 𝑃(−2.58 ≤\n𝑍 ≤ 2.58) is equal to _____.","page":37,"marks":1,"answer":"Central area: 0.99011997","steps":[{"title":"Standardize X","formula":"Use Z = (X − 0)/1, with Φ(z) = P(Z ≤ z)."},{"title":"Central area","formula":"Φ(2.58) − Φ(-2.58) ≈ 0.99011997."}],"shareImage":"share/q442.jpg","shareImageSize":[1358,219]},{"id":443,"question":"If 𝑍 is a standard normal variate, then 𝑃(|𝑍| <\n1.96) is equal to _____.","page":37,"marks":1,"answer":"Central area: 0.95000421","steps":[{"title":"Standardize X","formula":"Use Z = (X − 0)/1, with Φ(z) = P(Z ≤ z)."},{"title":"Central area","formula":"Φ(1.96) − Φ(-1.96) ≈ 0.95000421."}],"shareImage":"share/q443.jpg","shareImageSize":[1358,202]},{"id":444,"question":"For a normal distribution with 𝜇 = 10,𝜎 = 2, then\nprobability of a value greater than 10 is _____.","page":37,"marks":1,"answer":"Greater than 10: 0.5","steps":[{"title":"Standardize X","formula":"Use Z = (X − 10)/2, with Φ(z) = P(Z ≤ z)."},{"title":"Greater than 10","formula":"1 − Φ(0) ≈ 0.5."}],"shareImage":"share/q444.jpg","shareImageSize":[1358,215]},{"id":445,"question":"If x is normally distributed with mean 1 and\nvariance 4, then obtain k if P ( x  k ) = 0 . 9 0","page":37,"marks":1,"answer":"k: 3.5631031","steps":[{"title":"k","formula":"Use left-tail probability 0.9. z = Φ⁻¹(0.9) ≈ 1.2815516. x = μ + σz = 1 + 2 × (1.2815516) ≈ 3.5631031."}],"shareImage":"share/q445.jpg","shareImageSize":[1358,218]},{"id":446,"question":"The time to pass through a security screening at an\nairport follows an exponential distribution. The mean\ntime to pass through the security screening is 15\nminutes. To catch the flight, a passenger must clear th\nsecurity screening within 15 minutes. The probability\nthat the passenger will miss the flight is ______.","page":37,"marks":1,"answer":"Miss the flight: 0.36787944","steps":[{"title":"Use the exponential survival function","formula":"λ = 0.066666667. For t ≥ 0, P(X > t) = e^(−λt)."},{"title":"Miss the flight","formula":"e^(−1) ≈ 0.36787944."}],"shareImage":"share/q446.jpg","shareImageSize":[1358,341]},{"id":447,"question":"A variable 𝑋 is exponentially distributed for 𝑥 ≥ 0\nwith a mean of 1. The probability that the value of 𝑋\nwill lie between 1 and 2 is _____.","page":37,"marks":1,"answer":"Between 1 and 2: 0.23254416","steps":[{"title":"Use the exponential survival function","formula":"λ = 1. For t ≥ 0, P(X > t) = e^(−λt)."},{"title":"Between 1 and 2","formula":"e^(−1) − e^(−2) ≈ 0.23254416."}],"shareImage":"share/q447.jpg","shareImageSize":[1358,235]},{"id":448,"question":"A random variable 𝑃 follows exponential distribution\nwith mean value 0.5. The expectation of 𝑃2 will be","page":37,"marks":1,"answer":"0.5","steps":[{"title":"Set up the calculation","formula":"An exponential variable with mean 0.5 also has SD 0.5."},{"title":"Calculate","formula":"E[P²] = Var(P) + E[P]² = 0.5² + 0.5² = 0.5."}],"shareImage":"share/q448.jpg","shareImageSize":[1358,215]},{"id":449,"question":"Normal Distribution is symmetric about…..","page":37,"marks":1,"answer":"The mean μ","steps":[{"title":"Set up the calculation","formula":"The density depends on the squared distance (x−μ)²."},{"title":"Calculate","formula":"Points the same distance on either side of μ have the same density."}],"shareImage":"share/q449.jpg","shareImageSize":[1358,219]},{"id":450,"question":"A personal computer has the length of time\nbetween charges of the battery is normally\ndistributed with a mean of 66 hours and a standard\ndeviation of 20 hours. What is the probability when\nthe length of time will be between 58 and 75 hours?","page":38,"marks":1,"answer":"Between 58 and 75 hours: 0.32906652","steps":[{"title":"Standardize X","formula":"Use Z = (X − 66)/20, with Φ(z) = P(Z ≤ z)."},{"title":"Between 58 and 75 hours","formula":"Φ(0.45) − Φ(-0.4) ≈ 0.32906652."}],"shareImage":"share/q450.jpg","shareImageSize":[1358,297]},{"id":451,"question":"Approximately what area is covered under the\nnormal distribution curve between ±3 standard\ndeviation?","page":38,"marks":1,"answer":"Within three standard deviations: 0.9973002","steps":[{"title":"Standardize X","formula":"Use Z = (X − 0)/1, with Φ(z) = P(Z ≤ z)."},{"title":"Within three standard deviations","formula":"Φ(3) − Φ(-3) ≈ 0.9973002."}],"shareImage":"share/q451.jpg","shareImageSize":[1358,233]},{"id":452,"question":"An approximate area covered within two standard-\ndeviation of the mean by standard normal variate is","page":38,"marks":1,"answer":"Within two standard deviations: 0.95449974","steps":[{"title":"Standardize X","formula":"Use Z = (X − 0)/1, with Φ(z) = P(Z ≤ z)."},{"title":"Within two standard deviations","formula":"Φ(2) − Φ(-2) ≈ 0.95449974."}],"shareImage":"share/q452.jpg","shareImageSize":[1358,202]},{"id":453,"question":"Let X be a normal random variable with mean zero\nand variance 9. If 𝑎 = 𝑃(𝑋 ≥ 3), 𝑡ℎ𝑒𝑛 𝑃(|𝑋| ≤ 3)\nequal to….","page":38,"marks":1,"answer":"1 − 2a","steps":[{"title":"Set up the calculation","formula":"Symmetry gives P(X ≤ −3) = P(X ≥ 3) = a."},{"title":"Calculate","formula":"Subtract both tails from 1. Equality at individual points does not affect the probability."}],"shareImage":"share/q453.jpg","shareImageSize":[1358,234]},{"id":454,"question":"Let 𝑋 be normal variate with mean 0 and SD 5. If\n𝑃(𝑋 < 5) = 𝑘 then 𝑃(|𝑋| ≥ 5) will be","page":38,"marks":1,"answer":"2(1 − k)","steps":[{"title":"Set up the calculation","formula":"P(X ≥ 5) = 1 − k. Symmetry gives the same probability below −5."},{"title":"Calculate","formula":"Add the disjoint tails to obtain 2(1 − k)."}],"shareImage":"share/q454.jpg","shareImageSize":[1358,202]},{"id":455,"question":"The mean of a normal distribution is the average of\nthe first ten natural numbers then what is the\nprobability of variable between 4 and 7 if\n𝑃(𝑋 ≤ 4) = 1/5","page":38,"marks":1,"answer":"3/5","steps":[{"title":"Set up the calculation","formula":"The mean is (1+10)/2 = 5.5. The endpoints 4 and 7 are equally far from 5.5."},{"title":"Calculate","formula":"Each outside tail has probability 1/5. The middle has probability 1 − 2/5 = 3/5."}],"shareImage":"share/q455.jpg","shareImageSize":[1358,266]},{"id":456,"question":"For a standard normal variate, the value of mean is?","page":38,"marks":1,"answer":"0","steps":[{"title":"Set up the calculation","formula":"The standard normal distribution is N(0,1)."},{"title":"Calculate","formula":"Its first parameter, the mean, is 0."}],"shareImage":"share/q456.jpg","shareImageSize":[1358,190]},{"id":457,"question":"The standard normal curve is symmetric about the\nvalue….","page":38,"marks":1,"answer":"0","steps":[{"title":"Set up the calculation","formula":"The standard normal has μ = 0."},{"title":"Calculate","formula":"The density has the same height at z and −z, so its axis of symmetry is z = 0."}],"shareImage":"share/q457.jpg","shareImageSize":[1358,201]},{"id":458,"question":"For a standard normal probability distribution, the\nmean (µ) and the standard deviation (s)","page":38,"marks":1,"answer":"μ = 0, σ = 1","steps":[{"title":"Set up the calculation","formula":"Standardize by using Z = (X−μ)/σ."},{"title":"Calculate","formula":"Then E[Z] = 0 and Var(Z) = 1, giving SD = 1."}],"shareImage":"share/q458.jpg","shareImageSize":[1358,202]},{"id":459,"question":"If Y = 5X + 10 and X is N (10,25), then mean of Y\nis?","page":38,"marks":1,"answer":"60","steps":[{"title":"Set up the calculation","formula":"Linearity of expectation gives E[Y] = 5E[X] + 10."},{"title":"Calculate","formula":"E[Y] = 5(10) + 10 = 60."}],"shareImage":"share/q459.jpg","shareImageSize":[1358,221]},{"id":460,"question":"In a company, amount of light bills follows normal\ndistribution with 𝜎 = 60.\n11.31% of customers pay bill less than 260.The\naverage amount of light bill is _____.","page":38,"marks":1,"answer":"332.61234","steps":[{"title":"Set up the calculation","formula":"P(X < 260) = 0.1131 gives z = Φ⁻¹(0.1131) ≈ −1.21."},{"title":"Calculate","formula":"(260 − μ)/60 ≈ −1.21, so μ ≈ 332.6."}],"shareImage":"share/q460.jpg","shareImageSize":[1358,266]},{"id":461,"question":"If the distribution of a normal variable is shown as\n𝑁(20,4) then which of the following intervals\nincludes 99.73% observations?","page":38,"marks":1,"answer":"(14, 26)","steps":[{"title":"Set up the calculation","formula":"A central normal interval of roughly 99.73% is μ ± 3σ."},{"title":"Calculate","formula":"Here μ = 20 and σ = √4 = 2, so the endpoints are 20 ± 6."}],"shareImage":"share/q461.jpg","shareImageSize":[1358,234]},{"id":462,"question":"For Normal distribution with mean 2 and variance\n9. Find the value of x such that the probability of\nthe interval [2,𝑥] is 0.4115","page":38,"marks":1,"answer":"x: 6.0501495","steps":[{"title":"x","formula":"Use left-tail probability 0.9115. z = Φ⁻¹(0.9115) ≈ 1.3500498. x = μ + σz = 2 + 3 × (1.3500498) ≈ 6.0501495."}],"shareImage":"share/q462.jpg","shareImageSize":[1358,234]},{"id":463,"question":"If 𝑋 is a normal variate with a mean of 30 and an\nSD of 5, find (i) 𝑃(26 ≤ 𝑋 ≤ 40)\n(ii) 𝑃(𝑋 ≥ 45).","page":38,"marks":2,"answer":"Between 26 and 40: 0.76539447 · At least 45: 0.001349898","steps":[{"title":"Standardize X","formula":"Use Z = (X − 30)/5, with Φ(z) = P(Z ≤ z)."},{"title":"Between 26 and 40","formula":"Φ(2) − Φ(-0.8) ≈ 0.76539447."},{"title":"At least 45","formula":"1 − Φ(3) ≈ 0.001349898."}],"shareImage":"share/q463.jpg","shareImageSize":[760,235]},{"id":464,"question":"If 𝑋 is normally distributed with a mean of 2 and an\nSD of 0.1, find 𝑃(|𝑋 − 2| ≥ 0.01)?","page":38,"marks":2,"answer":"0.92034433","steps":[{"title":"Set up the calculation","formula":"The distances from mean 2 are ±0.01, giving z = ±0.1."},{"title":"Calculate","formula":"Add the two tails: 2Φ(−0.1) ≈ 0.92034."}],"shareImage":"share/q464.jpg","shareImageSize":[760,203]},{"id":465,"question":"Assume that the mean height of Indian soldiers is\n68.22 inches with a variance of 10.8 inches. How\nmany soldiers in a regiment of 1000 would you\nexpect to be over 6 feet tall?","page":38,"marks":3,"answer":"Over 72 inches: about 125 out of 1000","steps":[{"title":"Standardize X","formula":"Use Z = (X − 68.22)/3.2863353, with Φ(z) = P(Z ≤ z)."},{"title":"Over 72 inches","formula":"1 − Φ(1.1502174) ≈ 0.12502718. Multiply by 1000."}],"note":"Convert six feet to 72 inches and take the square root of the given variance.","shareImage":"share/q465.jpg","shareImageSize":[760,265]},{"id":466,"question":"The marks obtained by students in a college are\nnormally distributed with a mean of 65 and a\nvariance of 25. If 3 students are selected at random\nfrom this college, what is the probability that at\nleast one of them would have scored more than 75\nmarks?","page":38,"marks":3,"answer":"0.066709465","steps":[{"title":"Set up the calculation","formula":"A student scores at most 75 with probability Φ((75−65)/5) = Φ(2)."},{"title":"Calculate","formula":"Assuming independent selections, P(at least one above 75) = 1 − [Φ(2)]³."}],"shareImage":"share/q466.jpg","shareImageSize":[760,328]},{"id":467,"question":"If 𝑋 is normally distributed with a mean and\nstandard deviation of 4, find\n(i) 𝑃(5 ≤ 𝑋 ≤ 10) (ii) 𝑃(𝑋 ≥ 15)\n(iii) 𝑃(10 ≤ 𝑋 ≤ 15) (iv) 𝑃(𝑋 ≤ 5).","page":38,"marks":4,"answer":"Between 5 and 10: 0.33448647 · At least 15: 0.0029797632 · Between 10 and 15: 0.063827438 · At most 5: 0.59870633","steps":[{"title":"Standardize X","formula":"Use Z = (X − 4)/4, with Φ(z) = P(Z ≤ z)."},{"title":"Between 5 and 10","formula":"Φ(1.5) − Φ(0.25) ≈ 0.33448647."},{"title":"At least 15","formula":"1 − Φ(2.75) ≈ 0.0029797632."},{"title":"Between 10 and 15","formula":"Φ(2.75) − Φ(1.5) ≈ 0.063827438."},{"title":"At most 5","formula":"Φ(0.25) ≈ 0.59870633."}],"shareImage":"share/q467.jpg","shareImageSize":[760,267]},{"id":468,"question":"The compressive strength of samples of cement can\nbe modelled by a normal distribution with a mean\n6000 kilograms per square centimeter a standard\ndeviation of 100 kilograms per square centimeter.\n(i)What is the probability that a sample's strength is\nless than 6250 Kg/cm²?\n(ii) What is the probability if sample strength is\nbetween 5800 and 5900 Kg/cm²?\n(iii) What strength is exceeded by 95% of the\nsamples?","page":38,"marks":4,"answer":"(i) 0.99379033. (ii) 0.13590512. (iii) 5835.5146 kg/cm².","steps":[{"title":"Standardize the strength","formula":"Use z = (x−6000)/100."},{"title":"Calculate the two probabilities","formula":"(i) Φ(2.5). (ii) Φ(−1) − Φ(−2)."},{"title":"Find the strength exceeded by 95%","formula":"The left tail is 5%, so z = Φ⁻¹(0.05) ≈ −1.64485. Convert back using x = 6000 + 100z."}],"shareImage":"share/q468.jpg","shareImageSize":[760,511]},{"id":469,"question":"In a photographic process, the developing time of\nprints may be looked upon as a random variable\nhaving the normal distribution with a mean of 16.28\nseconds and a standard deviation of 0.12 second.\nFind the probability that it will take\n(i) anywhere from 16.00 to 16.50 seconds to develop\none of the prints;\n(ii) at least 16.20 seconds to develop one of the\nprints;\n(iii) at most 16.35 seconds to develop one of the\nprints.","page":39,"marks":4,"answer":"Between 16.00 and 16.50 seconds: 0.95680816 · At least 16.20 seconds: 0.74750746 · At most 16.35 seconds: 0.72016554","steps":[{"title":"Standardize X","formula":"Use Z = (X − 16.28)/0.12, with Φ(z) = P(Z ≤ z)."},{"title":"Between 16.00 and 16.50 seconds","formula":"Φ(1.8333333) − Φ(-2.3333333) ≈ 0.95680816."},{"title":"At least 16.20 seconds","formula":"1 − Φ(-0.66666667) ≈ 0.74750746."},{"title":"At most 16.35 seconds","formula":"Φ(0.58333333) ≈ 0.72016554."}],"shareImage":"share/q469.jpg","shareImageSize":[760,488]},{"id":470,"question":"Weights of 500 students of a college are normally\ndistributed with average weight 95 lbs and standard\ndeviation 7.5. find how many students have the\nweight between 100 and 110 lbs.","page":39,"marks":3,"answer":"Between 100 and 110 lb: about 115 out of 500","steps":[{"title":"Standardize X","formula":"Use Z = (X − 95)/7.5, with Φ(z) = P(Z ≤ z)."},{"title":"Between 100 and 110 lb","formula":"Φ(2) − Φ(0.66666667) ≈ 0.22974241. Multiply by 500."}],"shareImage":"share/q470.jpg","shareImageSize":[760,265]},{"id":471,"question":"Let X have density f(x) = (1/5)e^(−x/5) for x > 0, and 0 otherwise. Find (i) P(X > 5), (ii) P(3 ≤ X ≤ 6), (iii) its mean and (iv) its variance.","page":39,"marks":3,"answer":"P(X > 5): 0.36787944 · P(3 ≤ X ≤ 6): 0.24761742 · Mean = 5, variance = 25","steps":[{"title":"Use the exponential survival function","formula":"λ = 0.2. For t ≥ 0, P(X > t) = e^(−λt)."},{"title":"P(X > 5)","formula":"e^(−1) ≈ 0.36787944."},{"title":"P(3 ≤ X ≤ 6)","formula":"e^(−0.6) − e^(−1.2) ≈ 0.24761742."},{"title":"Find mean and variance","formula":"E[X] = 1/λ and Var(X) = 1/λ²."}],"shareImage":"share/q471.jpg","shareImageSize":[760,330]},{"id":472,"question":"If the weights of 300 students are normally\ndistributed with a mean of 68 kg and a standard\ndeviation of 3 kg, how many students have weights\n(i) greater than 72 kg? (ii) less than or equal to 64\nkg? (iii) between 65 kg and 71 kg inclusive?","page":39,"marks":4,"answer":"Above 72 kg: about 27 out of 300 · At most 64 kg: about 27 out of 300 · 65 to 71 kg: about 205 out of 300","steps":[{"title":"Standardize X","formula":"Use Z = (X − 68)/3, with Φ(z) = P(Z ≤ z)."},{"title":"Above 72 kg","formula":"1 − Φ(1.3333333) ≈ 0.09121122. Multiply by 300."},{"title":"At most 64 kg","formula":"Φ(-1.3333333) ≈ 0.09121122. Multiply by 300."},{"title":"65 to 71 kg","formula":"Φ(1) − Φ(-1) ≈ 0.68268949. Multiply by 300."}],"shareImage":"share/q472.jpg","shareImageSize":[760,300]},{"id":473,"question":"What is the probability that a standard normal\nvariate 𝑍 will be (i) greater than 1.09 ? (ii) less than\n−1.65? (iii) lying between −1 and 1.96? (iv) lying\nbetween 1.25 and 2.75?","page":39,"marks":4,"answer":"Greater than 1.09: 0.13785657 · Less than −1.65: 0.049471468 · Between −1 and 1.96: 0.81634685 · Between 1.25 and 2.75: 0.10267001","steps":[{"title":"Standardize X","formula":"Use Z = (X − 0)/1, with Φ(z) = P(Z ≤ z)."},{"title":"Greater than 1.09","formula":"1 − Φ(1.09) ≈ 0.13785657."},{"title":"Less than −1.65","formula":"Φ(-1.65) ≈ 0.049471468."},{"title":"Between −1 and 1.96","formula":"Φ(1.96) − Φ(-1) ≈ 0.81634685."},{"title":"Between 1.25 and 2.75","formula":"Φ(2.75) − Φ(1.25) ≈ 0.10267001."}],"shareImage":"share/q473.jpg","shareImageSize":[760,267]},{"id":474,"question":"The continuous random variable 𝑍 has a standard\nnormal distribution. Calculate the probability of the\nfollowing. (a) 𝑍 < 1.3 (b) 𝑍 > 1.3 (c) 𝑍 > −1.3\n(d) 𝑍 < −1.3 (e) −1.37 ≤ 𝑍 ≤ 2.01 (f) |𝑍| ≤ 0.5\n(g) −1.79 ≤ 𝑍 ≤ −0.54","page":39,"marks":5,"answer":"(a): 0.90319952 · (b): 0.096800485 · (c): 0.90319952 · (d): 0.096800485 · (e): 0.89244095 · (f): 0.38292492 · (g): 0.25787156","steps":[{"title":"Standardize X","formula":"Use Z = (X − 0)/1, with Φ(z) = P(Z ≤ z)."},{"title":"(a)","formula":"Φ(1.3) ≈ 0.90319952."},{"title":"(b)","formula":"1 − Φ(1.3) ≈ 0.096800485."},{"title":"(c)","formula":"1 − Φ(-1.3) ≈ 0.90319952."},{"title":"(d)","formula":"Φ(-1.3) ≈ 0.096800485."},{"title":"(e)","formula":"Φ(2.01) − Φ(-1.37) ≈ 0.89244095."},{"title":"(f)","formula":"Φ(0.5) − Φ(-0.5) ≈ 0.38292492."},{"title":"(g)","formula":"Φ(-0.54) − Φ(-1.79) ≈ 0.25787156."}],"shareImage":"share/q474.jpg","shareImageSize":[760,299]},{"id":475,"question":"Fit a normal distribution to the data below. Use μ = 43.7 and σ = 14.8.","page":39,"marks":4,"answer":"Expected frequencies in the printed classes: 9.5784991, 26.568755, 47.462307, 54.628759, 40.516898, 19.35945, 5.9559755.","steps":[{"title":"Set the parameters","formula":"Use the given mean and standard deviation. N = 208, μ ≈ 43.7, σ ≈ 14.8."},{"title":"Find the class boundaries","formula":"Boundaries: 10.5, 20.5, 30.5, 40.5, 50.5, 60.5, 70.5, 80.5. Use the midpoint between adjacent values or between the ends of adjacent classes."},{"title":"Calculate the expected frequencies","formula":"For each interval (a,b), calculate 208 × [Φ((b−μ)/σ) − Φ((a−μ)/σ)]. The two tails account for the fitted mass outside the listed classes."}],"table":{"headers":["Class or value","Frequency"],"rows":[["11–20",20],["21–30",28],["31–40",40],["41–50",60],["51–60",32],["61–70",20],["71–80",8]]},"workingTable":{"headers":["Class or value","Observed","Expected"],"rows":[["Below 10.5","","2.5876378"],["11–20",20,"9.5784991"],["21–30",28,"26.568755"],["31–40",40,"47.462307"],["41–50",60,"54.628759"],["51–60",32,"40.516898"],["61–70",20,"19.35945"],["71–80",8,"5.9559755"],["Above 80.5","","1.3417193"]]},"shareImage":"share/q475.jpg","shareImageSize":[760,547]},{"id":476,"question":"The income distribution of officers of a certain\ncompany was found to follow normal distribution.\nThe average income of an officer was Rs. 15,000.\nThe standard deviation of the income of officers\nwas Rs. 5,000. If there were 242 officers drawing\nsalary above Rs. 18,500, how many officers were\nthere in the company?","page":39,"marks":3,"answer":"About 1000 officers.","steps":[{"title":"Set up the calculation","formula":"P(salary > 18500) = 1 − Φ((18500−15000)/5000) = 1 − Φ(0.7)."},{"title":"Calculate","formula":"If there are N officers, N × [1 − Φ(0.7)] = 242. Divide 242 by this tail probability."}],"shareImage":"share/q476.jpg","shareImageSize":[760,389]},{"id":477,"question":"The life -time in hours of a certain electrical\nequipment has the normal distribution with mean =\n80 and standard deviation = 16. (i) What is the\nprobability that the equipment lasts at least\n100hours? (ii) If the equipment has already lasted\n88 hours, what is the conditional probability that it\nwill last at least another 12 hours?","page":40,"marks":3,"answer":"(i) 0.10564977. (ii) 0.34242113.","steps":[{"title":"Find the chance of lasting 100 hours","formula":"P(X ≥ 100) = 1 − Φ((100−80)/16) = 1 − Φ(1.25)."},{"title":"Condition on lasting 88 hours","formula":"Divide P(X ≥ 100) by P(X > 88) = 1 − Φ(0.5), since reaching 100 hours implies reaching 88 hours."}],"shareImage":"share/q477.jpg","shareImageSize":[760,363]},{"id":478,"question":"Find the area under the normal curve in each of the\ncases\n(I) In between z = – 0.68 and z = 0;\n(II) In between z = 0.81 and z = 1.94; and\n(III) Right of z = –1. 28.","page":40,"marks":3,"answer":"(i): 0.25174777 · (ii): 0.18278024 · (iii): 0.89972743","steps":[{"title":"Standardize X","formula":"Use Z = (X − 0)/1, with Φ(z) = P(Z ≤ z)."},{"title":"(i)","formula":"Φ(0) − Φ(-0.68) ≈ 0.25174777."},{"title":"(ii)","formula":"Φ(1.94) − Φ(0.81) ≈ 0.18278024."},{"title":"(iii)","formula":"1 − Φ(-1.28) ≈ 0.89972743."}],"shareImage":"share/q478.jpg","shareImageSize":[760,297]},{"id":479,"question":"Fit a normal distribution to the data below. Use μ = 165.5 and σ = 15.26.","page":40,"marks":3,"answer":"Expected frequencies in the printed classes: 0.85666284, 3.7357224, 10.752227, 20.438715, 25.669375, 21.303331, 11.681478, 4.230597, 1.0113365.","steps":[{"title":"Set the parameters","formula":"Use the given mean and standard deviation. N = 100, μ ≈ 165.5, σ ≈ 15.26."},{"title":"Find the class boundaries","formula":"Boundaries: 120, 130, 140, 150, 160, 170, 180, 190, 200, 210. Use the midpoint between adjacent values or between the ends of adjacent classes."},{"title":"Calculate the expected frequencies","formula":"For each interval (a,b), calculate 100 × [Φ((b−μ)/σ) − Φ((a−μ)/σ)]. The two tails account for the fitted mass outside the listed classes."}],"table":{"headers":["Class or value","Frequency"],"rows":[["125",1],["135",1],["145",14],["155",22],["165",25],["175",19],["185",13],["195",3],["205",2]]},"workingTable":{"headers":["Class or value","Observed","Expected"],"rows":[["Below 120","","0.14334914"],["125",1,"0.85666284"],["135",1,"3.7357224"],["145",14,"10.752227"],["155",22,"20.438715"],["165",25,"25.669375"],["175",19,"21.303331"],["185",13,"11.681478"],["195",3,"4.230597"],["205",2,"1.0113365"],["Above 210","","0.17720675"]]},"shareImage":"share/q479.jpg","shareImageSize":[760,332]},{"id":480,"question":"A random variable having the normal distribution\nwith𝜇 = 18.2,𝜎 = 1.25, find the probabilities that\nit will take on a value (i) less than 16.5, (ii)\nBetween 16.5 and 18.8.","page":40,"marks":3,"answer":"Below 16.5: 0.086914962 · Between 16.5 and 18.8: 0.59747134","steps":[{"title":"Standardize X","formula":"Use Z = (X − 18.2)/1.25, with Φ(z) = P(Z ≤ z)."},{"title":"Below 16.5","formula":"Φ(-1.36) ≈ 0.086914962."},{"title":"Between 16.5 and 18.8","formula":"Φ(0.48) − Φ(-1.36) ≈ 0.59747134."}],"shareImage":"share/q480.jpg","shareImageSize":[760,266]},{"id":481,"question":"Distribution of height of 1000 soldiers is normally\ndistributed with mean 165 cms and standard\ndeviation 15 cms. How many soldiers are of height\n(i) less than 138 cms (ii) more than 198 cms (iii)\nbetween 138 and 198 cms.","page":40,"marks":3,"answer":"Below 138 cm: about 36 out of 1000 · Above 198 cm: about 14 out of 1000 · 138 to 198 cm: about 950 out of 1000","steps":[{"title":"Standardize X","formula":"Use Z = (X − 165)/15, with Φ(z) = P(Z ≤ z)."},{"title":"Below 138 cm","formula":"Φ(-1.8) ≈ 0.035930319. Multiply by 1000."},{"title":"Above 198 cm","formula":"1 − Φ(2.2) ≈ 0.013903448. Multiply by 1000."},{"title":"138 to 198 cm","formula":"Φ(2.2) − Φ(-1.8) ≈ 0.95016623. Multiply by 1000."}],"shareImage":"share/q481.jpg","shareImageSize":[760,300]},{"id":482,"question":"In a normal distribution, 31% item are under 45 and\n8% are over 64. Find the mean and SD. Find also,\nthe percentage of items lying between 30 and 75.","page":40,"marks":5,"answer":"Mean ≈ 49.956099. SD ≈ 9.9951502. Between 30 and 75: 97.095239%.","steps":[{"title":"Convert both probabilities to z-scores","formula":"Φ⁻¹(0.31) = -0.49585035 and Φ⁻¹(0.92) = 1.4050716."},{"title":"Solve the two equations","formula":"45 = μ + (-0.49585035)σ and 64 = μ + (1.4050716)σ. Subtract to get σ ≈ 9.9951502, then substitute to get μ ≈ 49.956099."},{"title":"Between 30 and 75","formula":"Φ(2.5056053) − Φ(-1.9965782) ≈ 0.97095239."}],"shareImage":"share/q482.jpg","shareImageSize":[760,233]},{"id":483,"question":"Of a large group of men, 5% are under 60 inches in\nheight and 40% are between 60 and 65 inches.\nAssuming a normal distribution, find the mean and\nstandard deviation of distribution.","page":40,"marks":4,"answer":"Mean ≈ 65.413579. SD ≈ 3.2912226.","steps":[{"title":"Convert both probabilities to z-scores","formula":"Φ⁻¹(0.05) = -1.6448536 and Φ⁻¹(0.45) = -0.12566135."},{"title":"Solve the two equations","formula":"60 = μ + (-1.6448536)σ and 65 = μ + (-0.12566135)σ. Subtract to get σ ≈ 3.2912226, then substitute to get μ ≈ 65.413579."}],"shareImage":"share/q483.jpg","shareImageSize":[760,266]},{"id":484,"question":"In a large group of 400 females, 28% have a weight\nless than 55 kg, and 67% have a weight between 55\nand 62 kg. Assuming a normal distribution, find the\nmean and standard deviation of the distribution.\nAlso, determine how many females have a weight\ngreater than 65 kg.","page":40,"marks":4,"answer":"Mean ≈ 56.83144. SD ≈ 3.1422612. Above 65 kg: about 2.","steps":[{"title":"Convert both probabilities to z-scores","formula":"Φ⁻¹(0.28) = -0.58284151 and Φ⁻¹(0.95) = 1.6448536."},{"title":"Solve the two equations","formula":"55 = μ + (-0.58284151)σ and 62 = μ + (1.6448536)σ. Subtract to get σ ≈ 3.1422612, then substitute to get μ ≈ 56.83144."},{"title":"Above 65 kg","formula":"1 − Φ(2.5995801) ≈ 0.0046668944. Multiply by 400."}],"shareImage":"share/q484.jpg","shareImageSize":[760,329]},{"id":485,"question":"Of a large group of men, 15% are under 45 inches\nin height and 70% are between 45 and 65 inches.\nAssuming a normal distribution, find the mean and\nstandard deviation of distribution.","page":40,"marks":4,"answer":"Mean ≈ 55. SD ≈ 9.6484734.","steps":[{"title":"Convert both probabilities to z-scores","formula":"Φ⁻¹(0.15) = -1.0364334 and Φ⁻¹(0.85) = 1.0364334."},{"title":"Solve the two equations","formula":"45 = μ + (-1.0364334)σ and 65 = μ + (1.0364334)σ. Subtract to get σ ≈ 9.6484734, then substitute to get μ ≈ 55."}],"shareImage":"share/q485.jpg","shareImageSize":[760,265]},{"id":486,"question":"The marks of 1000 students of a university are\nfound to be normally distributed with a mean of 70\nand a standard of deviation 5. Estimate the number\nof students whose marks will be (i) between 60 and\n75, (ii) more than 75, and (iii) less than 68.","page":40,"marks":4,"answer":"Between 60 and 75: about 819 out of 1000 · Above 75: about 159 out of 1000 · Below 68: about 345 out of 1000","steps":[{"title":"Standardize X","formula":"Use Z = (X − 70)/5, with Φ(z) = P(Z ≤ z)."},{"title":"Between 60 and 75","formula":"Φ(1) − Φ(-2) ≈ 0.81859461. Multiply by 1000."},{"title":"Above 75","formula":"1 − Φ(1) ≈ 0.15865525. Multiply by 1000."},{"title":"Below 68","formula":"Φ(-0.4) ≈ 0.34457826. Multiply by 1000."}],"shareImage":"share/q486.jpg","shareImageSize":[760,297]},{"id":487,"question":"The lifetime of a certain batteries has a mean life of\n400 hours and the standard deviation as 45 hours.\nAssuming the distribution of lifetime to be normal,\nfind (i) the percentage of batteries with a lifetime of\nat least 470 hours, (ii) the proportion of batteries\nwith a lifetime between 385 and 415 hours, and (iii)\nthe minimum life of the best 5% of batteries.","page":40,"marks":4,"answer":"(i) 5.9906907%. (ii) 0.26111732. (iii) 474.01841 hours.","steps":[{"title":"At least 470 hours","formula":"1 − Φ((470−400)/45) ≈ 0.059906907."},{"title":"Between 385 and 415 hours","formula":"Φ(15/45) − Φ(−15/45) ≈ 0.26111732."},{"title":"Find the top 5% threshold","formula":"Use the 95th percentile: 400 + 45Φ⁻¹(0.95) ≈ 474.01841."}],"shareImage":"share/q487.jpg","shareImageSize":[760,360]},{"id":488,"question":"The marks obtained by students in an examination\nfollow a normal distribution. If 30% of the students\ngot marks below 35 and 10% got marks above 60,\nfind the mean and percentage of students who got\nmarks between 40 and 50.","page":40,"marks":5,"answer":"Mean ≈ 42.259336. SD ≈ 13.843114. Between 40 and 50: 27.680089%.","steps":[{"title":"Convert both probabilities to z-scores","formula":"Φ⁻¹(0.3) = -0.52440051 and Φ⁻¹(0.9) = 1.2815516."},{"title":"Solve the two equations","formula":"35 = μ + (-0.52440051)σ and 60 = μ + (1.2815516)σ. Subtract to get σ ≈ 13.843114, then substitute to get μ ≈ 42.259336."},{"title":"Between 40 and 50","formula":"Φ(0.55917073) − Φ(-0.1632101) ≈ 0.27680089."}],"shareImage":"share/q488.jpg","shareImageSize":[760,316]},{"id":489,"question":"Find the mean and standard deviation in which 7%\nof items are under 35 and 89% are under 63.","page":41,"marks":4,"answer":"Mean ≈ 50.291365. SD ≈ 10.36147.","steps":[{"title":"Convert both probabilities to z-scores","formula":"Φ⁻¹(0.07) = -1.475791 and Φ⁻¹(0.89) = 1.2265281."},{"title":"Solve the two equations","formula":"35 = μ + (-1.475791)σ and 63 = μ + (1.2265281)σ. Subtract to get σ ≈ 10.36147, then substitute to get μ ≈ 50.291365."}],"shareImage":"share/q489.jpg","shareImageSize":[760,201]},{"id":490,"question":"If X is a normal variate with a mean of 120 and a\nstandard deviation of 10, fine c such that\n(1) 𝑃( 𝑋 > 𝑐 ) = 0.02 and (2) 𝑃( 𝑋 < 𝑐 ) = 0.05","page":41,"marks":4,"answer":"(i) Upper 2% cutoff: 140.53749 · (ii) Lower 5% cutoff: 103.55146","steps":[{"title":"(i) Upper 2% cutoff","formula":"Use left-tail probability 0.98. z = Φ⁻¹(0.98) ≈ 2.0537489. x = μ + σz = 120 + 10 × (2.0537489) ≈ 140.53749."},{"title":"(ii) Lower 5% cutoff","formula":"Use left-tail probability 0.05. z = Φ⁻¹(0.05) ≈ -1.6448536. x = μ + σz = 120 + 10 × (-1.6448536) ≈ 103.55146."}],"shareImage":"share/q490.jpg","shareImageSize":[760,234]},{"id":491,"question":"If X is a normal variate with a mean of 25 and SD\nof 5, Find the value of 𝑋 = 𝑥 such that\n1\n𝑃(𝑋 ≤ 𝑥 ) = 0.01\n1","page":41,"marks":4,"answer":"Lower 1% cutoff: 13.368261","steps":[{"title":"Lower 1% cutoff","formula":"Use left-tail probability 0.01. z = Φ⁻¹(0.01) ≈ -2.3263479. x = μ + σz = 25 + 5 × (-2.3263479) ≈ 13.368261."}],"shareImage":"share/q491.jpg","shareImageSize":[760,235]},{"id":492,"question":"If 𝑋 is normal variate with a mean of 30 and an SD\nof 6, find the value of 𝑋 = 𝑥 such that\n1\n𝑃(𝑋 ≤ 𝑥 ) = 0.05.\n1","page":41,"marks":4,"answer":"Lower 5% cutoff: 20.130878","steps":[{"title":"Lower 5% cutoff","formula":"Use left-tail probability 0.05. z = Φ⁻¹(0.05) ≈ -1.6448536. x = μ + σz = 30 + 6 × (-1.6448536) ≈ 20.130878."}],"shareImage":"share/q492.jpg","shareImageSize":[760,235]},{"id":493,"question":"Fit a normal distribution to the data below.","page":41,"marks":4,"answer":"Expected frequencies in the printed classes: 2.9030687, 30.86142, 148.00016, 322.14046, 319.36791, 144.20567, 29.5503, 2.731259.","steps":[{"title":"Set the parameters","formula":"Use class midpoints m. Compute μ = Σfm/N and σ = √[Σf(m−μ)²/N]. N = 1000, μ ≈ 79.945, σ ≈ 5.4449036."},{"title":"Find the class boundaries","formula":"Boundaries: 60, 65, 70, 75, 80, 85, 90, 95, 100. Use the midpoint between adjacent values or between the ends of adjacent classes."},{"title":"Calculate the expected frequencies","formula":"For each interval (a,b), calculate 1000 × [Φ((b−μ)/σ) − Φ((a−μ)/σ)]. The two tails account for the fitted mass outside the listed classes."}],"table":{"headers":["Class or value","Frequency"],"rows":[["60–65",3],["65–70",21],["70–75",150],["75–80",335],["80–85",326],["85–90",135],["90–95",26],["95–100",4]]},"workingTable":{"headers":["Class or value","Observed","Expected"],"rows":[["Below 60","","0.12461083"],["60–65",3,"2.9030687"],["65–70",21,"30.86142"],["70–75",150,"148.00016"],["75–80",335,"322.14046"],["80–85",326,"319.36791"],["85–90",135,"144.20567"],["90–95",26,"29.5503"],["95–100",4,"2.731259"],["Above 100","","0.11513467"]]},"shareImage":"share/q493.jpg","shareImageSize":[760,423]},{"id":494,"question":"In an examination, it is laid down that a student\npasses if he secures 40% or more. He is placed in\nthe first, second and third division according to\nwhether he secures 60% or more marks, between\n50% and 60% marks and between 40% and 50%\nmarks respectively. He gets a distinction in case he\nsecures 75% or more. It is noticed from the result\nthat 10% of the students failed in the examination,\nwhereas 5% of them obtained distinction. Calculate\nthe percentage of students placed in the second\ndivision. (Assume Normal Distribution of marks.)","page":41,"marks":4,"answer":"Mean ≈ 55.327442. SD ≈ 11.960066. Second division: 32.398067%.","steps":[{"title":"Convert both probabilities to z-scores","formula":"Φ⁻¹(0.1) = -1.2815516 and Φ⁻¹(0.95) = 1.6448536."},{"title":"Solve the two equations","formula":"40 = μ + (-1.2815516)σ and 75 = μ + (1.6448536)σ. Subtract to get σ ≈ 11.960066, then substitute to get μ ≈ 55.327442."},{"title":"Second division","formula":"Φ(0.39067997) − Φ(-0.4454358) ≈ 0.32398067."}],"shareImage":"share/q494.jpg","shareImageSize":[760,488]},{"id":495,"question":"Let X have density f(x) = ce^(−2x) for x > 0. Find (i) P(X > 2) and (ii) P(X < 1/c).","page":41,"marks":3,"answer":"(i) P(X > 2): 0.018315639 · (ii) P(X < 1/c): 0.63212056","steps":[{"title":"Use the exponential survival function","formula":"λ = 2. For t ≥ 0, P(X > t) = e^(−λt)."},{"title":"(i) P(X > 2)","formula":"e^(−4) ≈ 0.018315639."},{"title":"(ii) P(X < 1/c)","formula":"e^(−0) − e^(−1) ≈ 0.63212056."}],"note":"Normalize first: ∫₀∞ ce^(−2x) dx = c/2 = 1, so c = 2 and 1/c = 1/2.","shareImage":"share/q495.jpg","shareImageSize":[760,249]},{"id":496,"question":"The mileage which car owners get with a certain\nkind of radial tire is a random variable having an\nexponential distribution with mean 4000 km. Find\nthe probabilities that one of these tires will last (i)\nat least 2000 km (ii) at most 3000 km.","page":41,"marks":3,"answer":"At least 2000 km: 0.60653066 · At most 3000 km: 0.52763345","steps":[{"title":"Use the exponential survival function","formula":"λ = 0.00025. For t ≥ 0, P(X > t) = e^(−λt)."},{"title":"At least 2000 km","formula":"e^(−0.5) ≈ 0.60653066."},{"title":"At most 3000 km","formula":"e^(−0) − e^(−0.75) ≈ 0.52763345."}],"shareImage":"share/q496.jpg","shareImageSize":[760,297]},{"id":497,"question":"The average time it takes to serve a customer at a\npetrol pump is 6 minutes. The service time follows\nexponential distribution. Calculate the probability\nthat (i) A customer will take less than 2 minutes to\ncomplete the service. (ii) A customer will take\nbetween 4 and 5 minutes to get the service. (iii) A\ncustomer will take more than 10 minutes for his\nservice.","page":41,"marks":4,"answer":"Under two minutes: 0.28346869 · Four to five minutes: 0.078818911 · More than ten minutes: 0.1888756","steps":[{"title":"Use the exponential survival function","formula":"λ = 0.16666667. For t ≥ 0, P(X > t) = e^(−λt)."},{"title":"Under two minutes","formula":"e^(−0) − e^(−0.33333333) ≈ 0.28346869."},{"title":"Four to five minutes","formula":"e^(−0.66666667) − e^(−0.83333333) ≈ 0.078818911."},{"title":"More than ten minutes","formula":"e^(−1.6666667) ≈ 0.1888756."}],"shareImage":"share/q497.jpg","shareImageSize":[760,392]},{"id":498,"question":"Daily milk consumption above 20,000 gallons is exponential with rate 1/3000. The daily stock is 35,000 gallons. Find the probability that the stock is insufficient on both of two randomly selected days.","page":41,"marks":4,"answer":"4.539993e-05","steps":[{"title":"Set up the calculation","formula":"Stock is insufficient when the excess over 20,000 gallons exceeds 15,000 gallons."},{"title":"Calculate","formula":"One day: e^(−15000/3000) = e⁻⁵. For two independent days, square it: e⁻¹⁰."}],"shareImage":"share/q498.jpg","shareImageSize":[760,341]},{"id":499,"question":"The lifetime 𝑇 of an alkline battery is exponentially\ndistributed with 𝜆 = 0.05 per hour.\n(a) What are the mean are standard deviation of the\nbattery’s lifetime?\n(b) What are the probabilities for the battery to last\nbetween 10 and 15 hours and to last more than 20\nhours?","page":41,"marks":4,"answer":"Between 10 and 15 hours: 0.13416411 · Over 20 hours: 0.36787944 · Mean = SD = 20 hours","steps":[{"title":"Use the exponential survival function","formula":"λ = 0.05. For t ≥ 0, P(X > t) = e^(−λt)."},{"title":"Between 10 and 15 hours","formula":"e^(−0.5) − e^(−0.75) ≈ 0.13416411."},{"title":"Over 20 hours","formula":"e^(−1) ≈ 0.36787944."},{"title":"Find mean and SD","formula":"For an exponential lifetime, both are 1/λ = 1/0.05 = 20 hours."}],"shareImage":"share/q499.jpg","shareImageSize":[760,392]},{"id":500,"question":"The time between breakdown of a particular\nmachine follows an exponential distribution with a\nmean of 17 days. Calculate the probability that a\nmachine breaks down in a 15 day period.","page":42,"marks":3,"answer":"Breakdown within 15 days: 0.5861919","steps":[{"title":"Use the exponential survival function","formula":"λ = 0.058823529. For t ≥ 0, P(X > t) = e^(−λt)."},{"title":"Breakdown within 15 days","formula":"e^(−0) − e^(−0.88235294) ≈ 0.5861919."}],"shareImage":"share/q500.jpg","shareImageSize":[760,266]},{"id":501,"question":"Machine repair time X is exponential with rate 1/2 per hour. Find (i) P(X > 2) and (ii) P(X ≥ 11 | X > 8).","page":42,"marks":3,"answer":"Repair time exceeds two hours: 0.36787944 · At least 11 hours given over eight hours: 0.22313016","steps":[{"title":"Use the exponential survival function","formula":"λ = 0.5. For t ≥ 0, P(X > t) = e^(−λt)."},{"title":"Repair time exceeds two hours","formula":"e^(−1) ≈ 0.36787944."},{"title":"At least 11 hours given over eight hours","formula":"e^(−1.5) ≈ 0.22313016."}],"note":"The exponential distribution is memoryless. Conditional on already taking eight hours, the chance of taking at least three more hours is P(X ≥ 3).","shareImage":"share/q501.jpg","shareImageSize":[760,343]},{"id":502,"question":"The Life length X of an electronic component\nfollows an exponential distribution. These are 2\nProcesses by which the component may be\nmanufactured. The Expected life length of\ncomponent is 100 hrs if process I is used to\nmanufacture while it is 150 hrs if process II is used.\nThe cost of manufacturing a single component by\nprocess I is Rs. 10, while is Rs.20 for Process II.\nMoreover, if the component lasts less than the\nguaranteed life of 200 hrs, a loss of Rs. 50 is to be\nborne by the manufacturer. Which process is\nAdvantageous to the manufacturer?","page":42,"marks":5,"answer":"Process I. Expected costs: Rs. 53.23 and Rs. 56.82.","steps":[{"title":"Set up the calculation","formula":"For mean m, the chance of a warranty loss is P(X < 200) = 1 − e^(−200/m)."},{"title":"Calculate","formula":"Process I: 10 + 50(1 − e⁻²). Process II: 20 + 50(1 − e^(−200/150)). Choose the smaller expected cost."}],"shareImage":"share/q502.jpg","shareImageSize":[760,519]},{"id":503,"question":"The length of the shower on a tropical island during\nrainy season has an exponential distribution, with\nparameter λ = 2, time being measured in minutes.\nWhat is the probability that a shower will last more\nthan three minutes? If a shower has already lasted\nfor 2 minutes, what is the probability that it will last\nfor at least one more minute?","page":42,"marks":3,"answer":"More than three minutes: 0.0024787522 · At least one more minute given two elapsed: 0.13533528","steps":[{"title":"Use the exponential survival function","formula":"λ = 2. For t ≥ 0, P(X > t) = e^(−λt)."},{"title":"More than three minutes","formula":"e^(−6) ≈ 0.0024787522."},{"title":"At least one more minute given two elapsed","formula":"e^(−2) ≈ 0.13533528."}],"note":"The exponential distribution is memoryless, so the second event uses the one-minute survival probability.","shareImage":"share/q503.jpg","shareImageSize":[760,361]},{"id":504,"question":"The life of an electronic component follows\nexponential distribution with a mean of 4 years.\nThe manufacturer of this component gives a\nreplacement warranty of 3 years.\n(a) What proportion of components will be\nreplaced in the period of warranty?\n(b) What is the probability that a randomly selected\ncomponent will have life within two standard\ndeviations of the mean life?","page":42,"marks":4,"answer":"Replaced under warranty: 0.52763345 · Within two standard deviations of the mean: 0.95021293","steps":[{"title":"Use the exponential survival function","formula":"λ = 0.25. For t ≥ 0, P(X > t) = e^(−λt)."},{"title":"Replaced under warranty","formula":"e^(−0) − e^(−0.75) ≈ 0.52763345."},{"title":"Within two standard deviations of the mean","formula":"e^(−0) − e^(−3) ≈ 0.95021293."}],"note":"Mean and SD both equal four years. The interval [4−8, 4+8] meets the support in [0,12].","shareImage":"share/q504.jpg","shareImageSize":[760,424]},{"id":505,"question":"If 𝑋 isan exponentially distributed random variable\nwith parameter 𝜆, find the value of k such that\n𝑃(𝑋 > 𝑘) = 𝑎𝑃(𝑋 ≤ 𝑘)","page":42,"marks":3,"answer":"k = ln((1+a)/a)/λ for a > 0","steps":[{"title":"Set up the calculation","formula":"Use e^(−λk) = a(1 − e^(−λk)) for k ≥ 0."},{"title":"Calculate","formula":"Rearrange to e^(−λk) = a/(1+a), then take logs. For a = 0 there is no finite solution."}],"shareImage":"share/q505.jpg","shareImageSize":[760,235]},{"id":506,"question":"The length of time X to complete a job is\nexponentially distributed with 𝐸(𝑋) = µ = 10\nhours. (i) Compute the probability of job\ncompletion between two consecutive jobs\nexceeding 20 hours. (ii) The cost of job completion\nis given by 𝐶 = 4 + 2𝑋 + 4𝑋2. Find the expected\nvalue of C.","page":42,"marks":3,"answer":"Time exceeds 20 hours: 0.13533528 · E[C] = 824","steps":[{"title":"Use the exponential survival function","formula":"λ = 0.1. For t ≥ 0, P(X > t) = e^(−λt)."},{"title":"Time exceeds 20 hours","formula":"e^(−2) ≈ 0.13533528."},{"title":"Find the expected cost","formula":"E[X] = 10 and E[X²] = Var(X) + E[X]² = 100 + 100 = 200. Therefore E[C] = 4 + 2(10) + 4(200) = 824."}],"shareImage":"share/q506.jpg","shareImageSize":[760,362]},{"id":507,"question":"In a newly constructed township, 2000 electric\nlamps are installed with an average life of 1000\nburning hours and standard deviation of 200 hours.\nAssuming the life of the lamps follows normal\ndistribution, find (𝑖) The number of lamps expected\nto fail during the first 700 hours.(𝑖𝑖) In which\nperiod of burning hours 10% of the lamps fail.","page":42,"marks":3,"answer":"(i) About 134 lamps. (ii) About 743.69 hours.","steps":[{"title":"Count failures before 700 hours","formula":"z = (700−1000)/200 = −1.5. Expected failures = 2000Φ(−1.5) ≈ 133.6144."},{"title":"Find when 10% have failed","formula":"The tenth percentile is 1000 + 200Φ⁻¹(0.10) ≈ 743.68969 hours."}],"shareImage":"share/q507.jpg","shareImageSize":[760,364]}]};
